import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import PostCard from '../components/PostCard';

const Profile = () => {
  const { id } = useParams();
  const { user: currentUser, updateUser } = useAuth();
  const [profileUser, setProfileUser] = useState(null);
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isFollowing, setIsFollowing] = useState(false);

  const userId = id || currentUser?.id;

  useEffect(() => {
    fetchProfile();
  }, [userId]);

  const fetchProfile = async () => {
    setLoading(true);
    try {
      const userRes = await axios.get(`http://localhost:5000/api/users/${userId}`);
      setProfileUser(userRes.data);
      
      const postsRes = await axios.get(`http://localhost:5000/api/posts/user/${userId}`);
      setPosts(postsRes.data);
      
      if (currentUser) {
        setIsFollowing(userRes.data.followers?.includes(currentUser.id));
      }
    } catch (err) {
      console.error('Error fetching profile:', err);
    }
    setLoading(false);
  };

  const handleFollow = async () => {
    try {
      const res = await axios.put(`http://localhost:5000/api/users/follow/${userId}`);
      setIsFollowing(!isFollowing);
      
      // Update current user's following list
      if (currentUser) {
        const updatedUser = { ...currentUser };
        if (isFollowing) {
          updatedUser.following = updatedUser.following.filter(id => id !== userId);
        } else {
          updatedUser.following = [...updatedUser.following, userId];
        }
        updateUser(updatedUser);
      }
      
      // Update profile user's followers count
      setProfileUser(prev => ({
        ...prev,
        followers: isFollowing 
          ? prev.followers.filter(id => id !== currentUser.id)
          : [...prev.followers, currentUser.id]
      }));
    } catch (err) {
      console.error('Error following user:', err);
    }
  };

  if (loading) return <div className="loading">Loading...</div>;
  if (!profileUser) return <div className="error">User not found</div>;

  const isOwnProfile = userId === currentUser?.id;

  return (
    <div className="profile-container">
      <div className="profile-header">
        <img 
          src={profileUser.profilePicture || '/default-avatar.png'} 
          alt={profileUser.username}
          className="profile-avatar"
        />
        <div className="profile-info">
          <h2>{profileUser.username}</h2>
          <p className="bio">{profileUser.bio || 'No bio yet'}</p>
          <div className="profile-stats">
            <span>{profileUser.followers?.length || 0} Followers</span>
            <span>{profileUser.following?.length || 0} Following</span>
          </div>
          {!isOwnProfile && (
            <button className={`follow-btn ${isFollowing ? 'following' : ''}`} onClick={handleFollow}>
              {isFollowing ? 'Unfollow' : 'Follow'}
            </button>
          )}
        </div>
      </div>

      <div className="profile-posts">
        <h3>Posts</h3>
        {posts.length === 0 ? (
          <p>No posts yet</p>
        ) : (
          posts.map(post => (
            <PostCard 
              key={post._id} 
              post={post} 
              onUpdate={fetchProfile}
              onDelete={fetchProfile}
            />
          ))
        )}
      </div>
    </div>
  );
};

export default Profile;
